a('S₀=P₂ and frontier',r'\unsure{two dots S_0|S_0}=\unsure{P|\mathcal P}_2(L); \unsure{dot A|bar A}',r'\mathfrak S_0=\mathfrak P_2(L); dot A',r'\unsure{two dots S_0|S_0}=P_2(L); dot A','P has one staff and angular bowl. Small detached mark over A is much narrower than A; two dots by S remain ambiguous.','005_middle.jpg','misread symbol or index','medium')
a('definition lead-in and inserted phrase',r'Pour \unsure{le|la} formuler, on définit \unsure{la|a}; structure \inserted{de \unsure{Réseau|réseau}} discrète',r'\uncertain{Pour un} \ill{} \ill{}; \ill{} définit un réseau, \ill{}; structure discrète',r'Pour le formuler, on définit \unsure{la|a}; structure \inserted{de Réseau} discrète','Le is a single tall stroke with low e; formuler has its long f. The curved insertion leader attaches de Réseau between structure and discrète, not as a separate sentence.','005_middle.jpg','insertion or placement','medium',marked=True)
