a('first display',r'Mod_f(\unsure{L|L_0})=\deleted{\unsure{Mod}}P_f(L)',r'Modf(L)=\mathfrak P_f(L)',r'Modf(\unsure{L|L_0})=\deleted{\unsure{Mod}}P_f(L)','Full-height f; looped argument is overwritten enough to leave L/L_0 uncertain. Cancelled Mod-like word before P is present.','005_bottom.jpg','omission','medium')
